    (v_route, 'Katedrála svatého Jana Křtitele v Trnavě', 'Kostel v Trnavě. Památka v Slovensku — kus historie přímo u trasy.', 48.3804, 17.58809, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20-%20Cathedral%20of%20St.%20John%20the%20Baptist.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trnava%20-%20Cathedral%20of%20St.%20John%20the%20Baptist.jpg"}'::text[], 0, '{"en": {"name": "St. John the Baptist Cathedral", "description": "Cathedral in Trnava. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Kathedrale des heiligen Johannes des Täufers", "description": "Kathedrale in Trnava. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra św. Jana Chrzciciela w Trnawie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Kathedraal van Johannes de Doper", "description": "Kathedraal in Trnava. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Juan Bautista", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Jean-Baptiste de Trnava", "description": "Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Katedrála svatého Jana Křtitele v Trnavě", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
