    (v_route, 'Šarišský hrad', 'Hrad na Slovensku. Hrad či zámek v Slovensku — historická zastávka, která stojí za odbočku.', 49.05222, 21.17611, 'http://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0ari%C5%A1sky%20hrad3.png', '{"http://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0ari%C5%A1sky%20hrad3.png"}'::text[], 0, '{"en": {"name": "Šariš Castle", "description": "Castle. A castle in Slovakia — a historic stop worth the detour."}, "de": {"name": "Burg Scharosch", "description": "Burg in der Slowakei. Eine Burg bzw. ein Schloss in der Slowakei — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Szaryski", "description": "Zamek w Słowacji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Šarišský hrad", "description": "Kasteel in Veľký Šariš, Slowakije. Een kasteel in Slowakije — een historische stop die de omweg waard is."}, "es": {"name": "Castillo de Šariš", "description": "Un castillo en Eslovaquia: una parada histórica que merece el desvío."}, "fr": {"name": "château de Šariš", "description": "Un château en Slovaquie — une halte historique qui vaut le détour."}, "uk": {"name": "Шаришський Град", "description": "Замок (споруда). Замок у Словаччині — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Konkatedrála svatého Mikuláše', 'Kostel v Prešově. Památka v Slovensku — kus historie přímo u trasy.', 48.99802, 21.23961, 'http://commons.wikimedia.org/wiki/Special:FilePath/Konkatedrala%20presov%20z%20vychodu.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Konkatedrala%20presov%20z%20vychodu.jpg"}'::text[], 1, '{"en": {"name": "Saint Nicholas Concathedral", "description": "Co-cathedral in Prešov, Slovakia. A heritage sight in Slovakia — a piece of history right on your route."}, "de": {"name": "Konkathedrale des heiligen Nikolaus", "description": "Gotische Hallenkirche in der Innenstadt von PreÅ¡ov. Ein Denkmal in der Slowakei — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Kościół św. Mikołaja w Preszowie", "description": "Zabytek w Słowacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Saint Nicholas Concathedral", "description": "Kathedraal in Prešov, Slowakije. Een monument in Slowakije — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Concatedral de San Nicolás", "description": "Un monumento en Eslovaquia: un pedazo de historia junto a la ruta."}, "fr": {"name": "concathédrale Saint-Nicolas de Prešov", "description": "Église à Prešov, Slovaquie. Un monument en Slovaquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Konkatedrála svatého Mikuláše", "description": "Пам''ятка в Словаччині — шматочок історії просто на маршруті."}}'::jsonb),
